esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We provide a payable fallback to allow receiving Ether if the inner call sends Ether to this contract.
    receive() external payable { }

    // Single public entry performing the property check.
    // Params: target address and arbitrary calldata. We use an address param so checker quantifies over callees.
    function run(address callee, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record C's balance before calling forward.
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // Call c.forward; capture whether it reverted. Must be top-level statement.
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: If the callee is this test contract, then whenever c.forward returns successfully (did not revert),
        // C's balance must not decrease (i.e., afterC >= beforeC). This asserts that a successful self-call cannot make C send Ether out.
        // We express it as: if callee == address(this) and not reverted then afterC >= beforeC.
        assert(!(callee == address(this) && !reverted) || afterC >= beforeC);
    }
}

